// === Tab: mySketch ===
// let can change with these values:

let sides = 4;
let delay = 40; // this will automatically reduce over time

let bg = color(230);
let fg = color(0);

let targetFps = 30;

// let don't mess with what's below unless you know what you're doing :)

function setup() {
  //createCanvas(windowWidth, windowHeight, WEBGL);
	createCanvas(1112, 834);
  strokeWeight(4);
  frameRate(targetFps);
}

let primes = [2, 3, 5, 7, 11, 13];

let nowSide = 0;
let remain = 0;
let xs = new Array(200);
let ys = new Array(200);

let x = 0, y = 0;
let ptx = x, pty = y, tx = x, ty = y;
let number = 0;
let rot = 0;
let zoom = 0;

function draw() {
	if(mousePressed)  {
		zoom+=(0.6-zoom)/16;
	} else  {
		zoom+=(1-zoom)/16;
	}
  ptx+=(x-ptx)/64;
  pty+=(y-pty)/64;  
  tx+=(ptx-tx)/64;
  ty+=(pty-ty)/64;
  background(bg);
  rot+=0.0005;

  translate(width/2, height/2);
  rotate(rot);
	scale(zoom);

  translate(-tx, -ty);
  number += (float(xs.length) - number)/16;
  stroke(lerpColor(bg, fg, 0.8));
  for (i = 0; i<xs.length-1; i++) {
    line(xs[i], ys[i], xs[i+1], ys[i+1]);
  }

  stroke(fg);
  let last = xs.length-1;
  if (last>=0) {
    let v = 1-remain/delay;//(cos(remain/delay*PI)+1)/2; // smooth motion
    line(xs[last], ys[last], 
      lerp(xs[last], x, v), 
      lerp(ys[last], y, v));
  }

  remain--;
  if (remain<=0) {
    delay += (5-delay)/32; // faster every time!

    for(i = 0; i<xs.length-1; i++)  {
      xs[i] = xs[i+1];
      ys[i] = ys[i+1];
    }

    xs[xs.length-1] = x;
    ys[ys.length-1] = y;
    let magnitude = primes[int(random)(primes.length)] * 30;
    nowSide = (nowSide+1)%sides;
		if(nowSide<0.1)  {
			magnitude+=60;
		}
    x+=cos(TWO_PI*float(nowSide)/sides)*magnitude;
    y+=sin(TWO_PI*float(nowSide)/sides)*magnitude;
    remain = delay;
  }
}

